    println(base64AbsentOptionalPadding.encode(bytes))
    // PaddingOption.ABSENT_OPTIONAL allows both padded and unpadded decode inputs
    println(base64AbsentOptionalPadding.decode("3i0CwA").toHexString(format))
    println(base64AbsentOptionalPadding.decode("3i0CwA==").toHexString(format))
